# D27 · Part 0~6 · 오늘의 흐름 전체: Frame · Processor · Pipeline으로 STT → LLM → TTS 한 턴 — 단독 실행 완성 코드 (Python 3.11)
# pip install (없음 · 표준 라이브러리만)
# 실행: python d27_flow.py   (Pipecat 없이 같은 구조의 미니 파이프라인 · 인터넷·GPU·마이크·API 키 불필요)
#   (대체: pipecat-ai 대신 같은 이름의 Frame·FrameProcessor·push_frame을 이 파일에서 직접 구현, STT·LLM·TTS는 사전 표로 흉내)
import asyncio
from dataclasses import dataclass

DOWN, UP = "downstream", "upstream"


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


@dataclass
class Frame:
    pass


@dataclass
class AudioFrame(Frame):
    tag: str = ""                                   # 대체: 실제 PCM 대신 '무슨 말인지' 꼬리표


@dataclass
class TextFrame(Frame):
    text: str = ""


@dataclass
class EndFrame(Frame):
    pass


class FrameProcessor:
    def __init__(self, name: str) -> None:
        self.name, self.nxt, self.prv = name, None, None

    async def push_frame(self, frame: Frame, direction: str = DOWN) -> None:
        target = self.nxt if direction == DOWN else self.prv
        if target:
            await target.process_frame(frame, direction)

    async def process_frame(self, frame: Frame, direction: str) -> None:
        await self.push_frame(frame, direction)       # 규칙: 모르는 Frame도 반드시 다음으로 넘긴다


class STT(FrameProcessor):
    async def process_frame(self, frame, direction):
        if isinstance(frame, AudioFrame):
            await self.push_frame(TextFrame({"hello": "안녕하세요 예약하고 싶어요"}[frame.tag]))
        else:
            await self.push_frame(frame, direction)


class LLM(FrameProcessor):
    async def process_frame(self, frame, direction):
        if isinstance(frame, TextFrame):
            await self.push_frame(TextFrame("네, 언제로 예약해 드릴까요?"))
        else:
            await self.push_frame(frame, direction)


class TTS(FrameProcessor):
    async def process_frame(self, frame, direction):
        if isinstance(frame, TextFrame):
            await self.push_frame(AudioFrame("tts:" + frame.text))
        else:
            await self.push_frame(frame, direction)


class Sink(FrameProcessor):
    def __init__(self, name: str) -> None:
        super().__init__(name)
        self.got: list[Frame] = []

    async def process_frame(self, frame, direction):
        self.got.append(frame)


async def main() -> None:
    src, stt, llm, tts, sink = FrameProcessor("src"), STT("stt"), LLM("llm"), TTS("tts"), Sink("sink")
    chain = [src, stt, llm, tts, sink]
    for a, b in zip(chain, chain[1:]):                # Pipeline = 작업자를 앞뒤로 이어 붙인 것
        a.nxt, b.prv = b, a
    await src.process_frame(AudioFrame("hello"), DOWN)
    await src.process_frame(EndFrame(), DOWN)
    kinds = [type(f).__name__ for f in sink.got]
    print("출구에 도착한 Frame:", kinds, "·", sink.got[0])
    check(kinds == ["AudioFrame", "EndFrame"] and sink.got[0].tag.startswith("tts:네, 언제로"), "STT → LLM → TTS를 거친 음성과 EndFrame이 도착해야 해요.")


asyncio.run(main())

