// D27 · Part 0~6 · 오늘의 흐름 전체: Frame · Processor · Pipeline으로 STT → LLM → TTS 한 턴 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d27_flow.ts
//   (대체: pipecat 대신 같은 이름의 Frame·FrameProcessor·pushFrame을 이 파일에서 직접 구현, STT·LLM·TTS는 사전 표로 흉내)
type Direction = "downstream" | "upstream";
const DOWN: Direction = "downstream";

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

interface Frame {
  kind: string;
  tag?: string; // 대체: 실제 PCM 대신 '무슨 말인지' 꼬리표
  text?: string;
}

class FrameProcessor {
  name: string;
  nxt: FrameProcessor | null = null;
  prv: FrameProcessor | null = null;
  constructor(name: string) {
    this.name = name;
  }
  async pushFrame(frame: Frame, direction: Direction = DOWN): Promise<void> {
    const target = direction === DOWN ? this.nxt : this.prv;
    if (target) await target.processFrame(frame, direction);
  }
  async processFrame(frame: Frame, direction: Direction): Promise<void> {
    await this.pushFrame(frame, direction); // 규칙: 모르는 Frame도 반드시 다음으로 넘긴다
  }
}

class STT extends FrameProcessor {
  async processFrame(frame: Frame, direction: Direction): Promise<void> {
    if (frame.kind === "AudioFrame") await this.pushFrame({ kind: "TextFrame", text: ({ hello: "안녕하세요 예약하고 싶어요" } as Record<string, string>)[frame.tag ?? ""] });
    else await this.pushFrame(frame, direction);
  }
}

class LLM extends FrameProcessor {
  async processFrame(frame: Frame, direction: Direction): Promise<void> {
    if (frame.kind === "TextFrame") await this.pushFrame({ kind: "TextFrame", text: "네, 언제로 예약해 드릴까요?" });
    else await this.pushFrame(frame, direction);
  }
}

class TTS extends FrameProcessor {
  async processFrame(frame: Frame, direction: Direction): Promise<void> {
    if (frame.kind === "TextFrame") await this.pushFrame({ kind: "AudioFrame", tag: "tts:" + frame.text });
    else await this.pushFrame(frame, direction);
  }
}

class Sink extends FrameProcessor {
  got: Frame[] = [];
  async processFrame(frame: Frame): Promise<void> {
    this.got.push(frame);
  }
}

const src = new FrameProcessor("src");
const sink = new Sink("sink");
const chain: FrameProcessor[] = [src, new STT("stt"), new LLM("llm"), new TTS("tts"), sink];
for (let i = 0; i + 1 < chain.length; i++) {
  // Pipeline = 작업자를 앞뒤로 이어 붙인 것
  chain[i].nxt = chain[i + 1];
  chain[i + 1].prv = chain[i];
}
await src.processFrame({ kind: "AudioFrame", tag: "hello" }, DOWN);
await src.processFrame({ kind: "EndFrame" }, DOWN);
const kinds = sink.got.map((f) => f.kind);
console.log("출구에 도착한 Frame:", kinds.join(","), "·", JSON.stringify(sink.got[0]));
check(kinds.join() === "AudioFrame,EndFrame" && (sink.got[0].tag ?? "").startsWith("tts:네, 언제로"), "STT → LLM → TTS를 거친 음성과 EndFrame이 도착해야 해요.");

frames.python:
# D27 · Part 1 · Frame 세 종류: System · Data · Control — 단독 실행 완성 코드 (Python 3.11)
# pip install (없음 · 표준 라이브러리만)
# 실행: python d27_frames.py   (Pipecat 없이 같은 분류 체계를 직접 구현 · 인터넷·GPU·마이크 불필요)
#   System = 즉시(큐를 새치기) · Data = 순서대로 · Control = 순서대로 + 시작·끝 신호
#   (대체: pipecat.frames.frames 대신 같은 이름의 클래스를 이 파일에서 정의)
import heapq
from dataclasses import dataclass


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


@dataclass
class Frame: pass
@dataclass
class SystemFrame(Frame): pass
@dataclass
class DataFrame(Frame): pass
@dataclass
class ControlFrame(Frame): pass
@dataclass
class StartFrame(SystemFrame): pass
@dataclass
class InputAudioRawFrame(SystemFrame): pass
@dataclass
class UserStartedSpeakingFrame(SystemFrame): pass
@dataclass
class TextFrame(DataFrame): text: str = ""
@dataclass
class OutputAudioRawFrame(DataFrame): pass
@dataclass
class EndFrame(ControlFrame): pass
@dataclass
class TTSStoppedFrame(ControlFrame): pass


def kind(f: Frame) -> str:
    """빈칸 1: Frame이 어느 종류인지 판정 (하위 클래스부터 isinstance로)."""
    if isinstance(f, SystemFrame):
        return "System"
    if isinstance(f, ControlFrame):
        return "Control"
    return "Data"


def deliver(frames: list[Frame]) -> list[str]:
    """한 작업자의 대기열: System은 앞으로 새치기, 나머지는 들어온 순서대로 처리."""
    heap = [(0 if isinstance(f, SystemFrame) else 1, i, type(f).__name__) for i, f in enumerate(frames)]
    heapq.heapify(heap)
    return [heapq.heappop(heap)[2] for _ in range(len(heap))]


sample = [StartFrame(), InputAudioRawFrame(), UserStartedSpeakingFrame(), TextFrame("안녕"), OutputAudioRawFrame(), TTSStoppedFrame(), EndFrame()]
for f in sample:
    print(f"{type(f).__name__:<26} → {kind(f)}")
queue = [TextFrame("a"), TextFrame("b"), UserStartedSpeakingFrame(), EndFrame()]      # 말이 시작되는 System이 뒤에 있어도
order = deliver(queue)
check([kind(f) for f in sample] == ["System"] * 3 + ["Data"] * 2 + ["Control"] * 2 and order[0] == "UserStartedSpeakingFrame" and order[1:] == ["TextFrame", "TextFrame", "EndFrame"],
      "System은 큐 맨 앞으로, Data·Control은 들어온 순서대로예요.")

frames.typescript:
// D27 · Part 1 · Frame 세 종류: System · Data · Control — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d27_frames.ts
//   System = 즉시(큐를 새치기) · Data = 순서대로 · Control = 순서대로 + 시작·끝 신호
//   (대체: pipecat 대신 같은 이름·같은 분류 체계를 이 파일에서 직접 정의)
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

type Kind = "System" | "Data" | "Control";
const CLASS_OF: Record<string, Kind> = {
  StartFrame: "System",
  InputAudioRawFrame: "System",
  UserStartedSpeakingFrame: "System",
  TextFrame: "Data",
  OutputAudioRawFrame: "Data",
  TTSStoppedFrame: "Control",
  EndFrame: "Control",
};

interface Frame {
  name: string;
}

function kind(f: Frame): Kind {
  // 빈칸 1: Frame이 어느 종류인지 판정
  return CLASS_OF[f.name];
}

function deliver(frames: Frame[]): string[] {
  // 한 작업자의 대기열: System은 앞으로 새치기, 나머지는 들어온 순서대로 처리
  const sys = frames.filter((f) => kind(f) === "System");
  const rest = frames.filter((f) => kind(f) !== "System");
  return [...sys, ...rest].map((f) => f.name);
}

const sample: Frame[] = ["StartFrame", "InputAudioRawFrame", "UserStartedSpeakingFrame", "TextFrame", "OutputAudioRawFrame", "TTSStoppedFrame", "EndFrame"].map((name) => ({ name }));
for (const f of sample) console.log(`${f.name.padEnd(26)} → ${kind(f)}`);
const order = deliver(["TextFrame", "TextFrame", "UserStartedSpeakingFrame", "EndFrame"].map((name) => ({ name }))); // 말이 시작되는 System이 뒤에 있어도
check(
  sample.map(kind).join() === "System,System,System,Data,Data,Control,Control" && order[0] === "UserStartedSpeakingFrame" && order.slice(1).join() === "TextFrame,TextFrame,EndFrame",
  "System은 큐 맨 앞으로, Data·Control은 들어온 순서대로예요.",
);

proc.typescript:
// D27 · Part 2 · Processor 안에서: 받고 → 일하고 → 넘기기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d27_proc.ts
//   숫자를 읽는 말로 바꾸는 KoNormalizer, 그리고 규칙 3(모르는 Frame도 넘기기)을 어긴 Forgetful 작업자 실험
//   (대체: pipecat 대신 이 파일의 FrameProcessor)
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

interface Frame {
  kind: string;
  text?: string;
}

class FrameProcessor {
  nxt: FrameProcessor | null = null;
  async pushFrame(frame: Frame): Promise<void> {
    if (this.nxt) await this.nxt.processFrame(frame);
  }
  async processFrame(frame: Frame): Promise<void> {
    await this.pushFrame(frame);
  }
}

class Recorder extends FrameProcessor {
  log: Frame[] = [];
  async processFrame(frame: Frame): Promise<void> {
    this.log.push(frame);
    await this.pushFrame(frame);
  }
}

const DIGITS = "영일이삼사오육칠팔구";

class KoNormalizer extends FrameProcessor {
  async processFrame(frame: Frame): Promise<void> {
    // 규칙 1: 내 일감(TextFrame)만 가공, 규칙 3: 나머지도 반드시 넘긴다
    if (frame.kind === "TextFrame") frame = { kind: "TextFrame", text: (frame.text ?? "").replace(/\d/g, (d) => DIGITS[Number(d)]) };
    await this.pushFrame(frame);
  }
}

class Forgetful extends FrameProcessor {
  async processFrame(frame: Frame): Promise<void> {
    if (frame.kind === "TextFrame") await this.pushFrame(frame); // TextFrame만 넘기고 EndFrame은 '깜빡'
  }
}

async function run(worker: FrameProcessor): Promise<string[]> {
  const rec = new Recorder();
  worker.nxt = rec;
  for (const f of [{ kind: "TextFrame", text: "3시 15분" }, { kind: "EndFrame" }]) await worker.processFrame(f);
  return rec.log.map((f) => (f.text ? `${f.kind}(${f.text})` : f.kind));
}

const good = await run(new KoNormalizer());
const bad = await run(new Forgetful());
console.log("KoNormalizer 뒤:", good.join(" | "));
console.log("Forgetful 뒤   :", bad.join(" | "), "← EndFrame이 사라져 뒤 작업자는 끝을 모른다");
check(good.join() === "TextFrame(삼시 일오분),EndFrame" && bad.join() === "TextFrame(3시 15분)", "숫자는 읽는 말로, EndFrame은 반드시 넘어가야 해요.");

dir.typescript:
// D27 · Part 3 · 방향: downstream · upstream, 그리고 Observer — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d27_dir.ts
//   뒤 작업자가 앞쪽으로 신호(upstream)를 보내고, Observer가 파이프라인을 바꾸지 않고 모든 push를 기록한다
//   (대체: pipecat의 BaseObserver 대신 pushFrame 안에서 공유 기록장에 적기)
type Direction = "downstream" | "upstream";
const DOWN: Direction = "downstream";
const UP: Direction = "upstream";
const TRACE: string[][] = []; // Observer: [보낸 이, 받는 이, Frame, 방향]

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

interface Frame {
  kind: string; // TextFrame · SlowDownFrame(직접 만든 Frame: 뒤에서 앞으로 '천천히' 요청)
}

class FrameProcessor {
  name: string;
  nxt: FrameProcessor | null = null;
  prv: FrameProcessor | null = null;
  received: string[] = [];
  constructor(name: string) {
    this.name = name;
  }
  async pushFrame(frame: Frame, direction: Direction = DOWN): Promise<void> {
    const target = direction === DOWN ? this.nxt : this.prv;
    if (target) {
      TRACE.push([this.name, target.name, frame.kind, direction]);
      await target.processFrame(frame, direction);
    }
  }
  async processFrame(frame: Frame, direction: Direction): Promise<void> {
    this.received.push(`${frame.kind}/${direction}`);
    await this.pushFrame(frame, direction);
  }
}

class Tail extends FrameProcessor {
  async processFrame(frame: Frame, direction: Direction): Promise<void> {
    this.received.push(`${frame.kind}/${direction}`);
    if (frame.kind === "TextFrame") await this.pushFrame({ kind: "SlowDownFrame" }, UP); // 빈칸 4: 앞쪽으로 보내려면 UP
  }
}

const ps = ["Source", "Normalizer", "TTS", "Tail"].map((n) => (n === "Tail" ? new Tail(n) : new FrameProcessor(n)));
for (let i = 0; i + 1 < ps.length; i++) {
  ps[i].nxt = ps[i + 1];
  ps[i + 1].prv = ps[i];
}
await ps[0].processFrame({ kind: "TextFrame" }, DOWN);
for (const t of TRACE) console.log(`${t[0].padStart(10)} → ${t[1].padEnd(10)} ${t[2].padEnd(14)} ${t[3]}`);
const ups = TRACE.filter((t) => t[3] === UP);
check(ups.map((t) => t[1]).join() === "TTS,Normalizer,Source" && ps[0].received.includes("SlowDownFrame/upstream") && TRACE.length === 6, "SlowDownFrame은 TTS → Normalizer → Source 순서로 거슬러 올라가야 해요.");

svc.typescript:
// D27 · Part 4 · 서비스 세 개: STT · LLM · TTS도 결국 FrameProcessor — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d27_svc.ts
//   STT(오디오 → 글자) · LLM(대화 기록 → 답) · TTS(글자 → 오디오, 오래 걸리는 합성은 await로 양보)를 한 줄로 이어 확인
//   (대체: Whisper·Qwen·Edge TTS 대신 사전 표와 setTimeout 모의 작업)
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

interface Frame {
  kind: string;
  tag?: string;
  text?: string;
}

class FrameProcessor {
  nxt: FrameProcessor | null = null;
  async pushFrame(frame: Frame): Promise<void> {
    if (this.nxt) await this.nxt.processFrame(frame);
  }
  async processFrame(frame: Frame): Promise<void> {
    await this.pushFrame(frame);
  }
}

class FakeSTT extends FrameProcessor {
  async processFrame(frame: Frame): Promise<void> {
    await this.pushFrame(frame.kind === "AudioFrame" ? { kind: "TextFrame", text: "내일 오후 세 시요" } : frame);
  }
}

class FakeLLM extends FrameProcessor {
  context: { role: string; content: string }[] = []; // LLM 서비스는 대화 전체(context)를 들고 있다
  async processFrame(frame: Frame): Promise<void> {
    if (frame.kind !== "TextFrame") return this.pushFrame(frame);
    const reply = `${frame.text}로 예약할게요.`;
    this.context.push({ role: "user", content: frame.text ?? "" }, { role: "assistant", content: reply });
    await this.pushFrame({ kind: "TextFrame", text: reply });
  }
}

class FakeTTS extends FrameProcessor {
  async synth(text: string): Promise<Buffer> {
    await new Promise((r) => setTimeout(r, 50)); // 오래 걸리는 합성 흉내 (await 하는 동안 이벤트 루프는 다른 일을 한다)
    return Buffer.from(text, "utf-8");
  }
  async processFrame(frame: Frame): Promise<void> {
    if (frame.kind !== "TextFrame") return this.pushFrame(frame);
    const audio = await this.synth(frame.text ?? "");
    await this.pushFrame({ kind: "AudioFrame", tag: `${audio.length}바이트` });
  }
}

class Out extends FrameProcessor {
  got: Frame[] = [];
  async processFrame(frame: Frame): Promise<void> {
    this.got.push(frame);
  }
}

const stt = new FakeSTT();
const llm = new FakeLLM();
const tts = new FakeTTS();
const out = new Out();
stt.nxt = llm;
llm.nxt = tts;
tts.nxt = out;
await stt.processFrame({ kind: "AudioFrame", tag: "a1" });
console.log("LLM 대화 기록:", JSON.stringify(llm.context));
console.log("출구:", JSON.stringify(out.got));
check(llm.context.map((m) => m.role).join() === "user,assistant" && out.got.length === 1 && out.got[0].tag === "44바이트" && llm.context[1].content === "내일 오후 세 시요로 예약할게요.", "STT 글자가 LLM 기록에 들어가고 TTS 오디오가 나와야 해요.");

