// D27 · Part 4 · 이벤트 루프 막힘: 20 ms 심장 박동이 멈추면 소리가 끊긴다 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d27_loop.ts   (모의 합성으로 약 1초)
//   20 ms마다 뛰는 heartbeat가 합성하는 150 ms 동안 몇 번 뛰는지 세서, 이벤트 루프를 붙잡는 동기 계산과 조각내어 양보하는 계산을 비교
//   (대체: 실제 TTS 합성 대신 150 ms 동안 도는 반복문)
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const sleep = (ms: number): Promise<void> => new Promise((r) => setTimeout(r, ms));

function spin(ms: number): void {
  // 막히는 합성: ms 동안 CPU를 붙잡는다
  const end = performance.now() + ms;
  while (performance.now() < end) {
    /* 계산 중 */
  }
}

async function measure(blocking: boolean): Promise<number> {
  // 합성(150 ms) 동안 뛴 박동 수
  let beats = 0;
  let stop = false;
  const beat = (async () => {
    while (!stop) {
      await sleep(20);
      beats++;
    }
  })();
  await sleep(100);
  const before = beats;
  if (blocking) spin(150); // 한 번에 150 ms → 루프가 멈춤
  else for (let i = 0; i < 15; i++) {
    spin(10); // 10 ms씩 15번 나눠 계산하고
    await sleep(0); // 사이사이 양보 → 루프가 계속 뜀 (Python의 to_thread 자리)
  }
  const during = beats - before;
  stop = true;
  await beat;
  return during;
}

const blocked = await measure(true);
const chunked = await measure(false);
console.log(`합성 150 ms 동안 박동: 한 번에 계산 ${blocked}번 · 조각 계산 ${chunked}번 (멈추지 않고 여러 번 뛰면 성공)`);
check(blocked <= 1 && chunked >= 4, "한 번에 계산하면 박동이 멈추고, 조각내면 계속 뛰어야 해요.");

assemble.python:
# D27 · Part 5 · 조립된 한 턴: VAD → STT → 사용자 턴 → LLM → TTS → 대화 기록 — 단독 실행 완성 코드 (Python 3.11)
# pip install (없음 · 표준 라이브러리만)
# 실행: python d27_assemble.py   (Pipecat 없이 가상 시계로 · 인터넷·GPU·마이크·API 키 불필요)
#   턴 끝 판정 = '0.6초 조용함(VAD)'과 '받아쓰기 도착' 중 늦은 쪽, 그 뒤 LLM·TTS 첫 소리까지가 사용자가 느끼는 응답 시간
#   (대체: 실제 시간 대신 프레임에 적힌 가상 시각 t(초) · LLM·TTS는 고정 지연 0.4초·0.2초)
import asyncio
from dataclasses import dataclass, field

STOP_SECS, LLM_TTFB, TTS_TTFB = 0.6, 0.4, 0.2


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


@dataclass
class Frame:
    t: float = 0.0                                     # 가상 시각(초)
@dataclass
class UserStoppedSpeakingFrame(Frame): pass
@dataclass
class TranscriptFrame(Frame): text: str = ""
@dataclass
class ContextFrame(Frame): messages: list = field(default_factory=list)
@dataclass
class TextFrame(Frame): text: str = ""
@dataclass
class AudioFrame(Frame): pass


class FrameProcessor:
    def __init__(self) -> None:
        self.nxt = None

    async def push_frame(self, frame: Frame) -> None:
        if self.nxt:
            await self.nxt.process_frame(frame)

    async def process_frame(self, frame: Frame) -> None:
        await self.push_frame(frame)


class UserAggregator(FrameProcessor):
    def __init__(self, context: list) -> None:
        super().__init__()
        self.context, self.stopped, self.text = context, None, None

    async def process_frame(self, frame):
        if isinstance(frame, UserStoppedSpeakingFrame):
            self.stopped = frame.t
        elif isinstance(frame, TranscriptFrame):
            self.text, self.arrived = frame.text, frame.t
        if self.stopped is not None and self.text is not None:     # 둘 다 모이면 턴 끝
            self.context.append({"role": "user", "content": self.text})
            end = max(self.stopped, self.arrived)
            self.stopped = self.text = None
            await self.push_frame(ContextFrame(end, list(self.context)))


class LLM(FrameProcessor):
    async def process_frame(self, frame):
        if isinstance(frame, ContextFrame):
            await self.push_frame(TextFrame(frame.t + LLM_TTFB, f"{frame.messages[-1]['content']}, 알겠습니다."))


class TTS(FrameProcessor):
    async def process_frame(self, frame):
        if isinstance(frame, TextFrame):
            await self.push_frame(frame)               # 글자는 대화 기록용으로도 흘려보내고
            await self.push_frame(AudioFrame(frame.t + TTS_TTFB))


class AssistantAggregator(FrameProcessor):
    def __init__(self, context: list) -> None:
        super().__init__()
        self.context, self.first_sound = context, []

    async def process_frame(self, frame):
        if isinstance(frame, TextFrame):
            self.context.append({"role": "assistant", "content": frame.text})
        elif isinstance(frame, AudioFrame):
            self.first_sound.append(frame.t)


async def main() -> None:
    ctx = [{"role": "system", "content": "치과 예약 비서"}]
    chain = [FrameProcessor(), UserAggregator(ctx), LLM(), TTS(), AssistantAggregator(ctx)]
    for a, b in zip(chain, chain[1:]):
        a.nxt = b
    # (말 끝 시각, 받아쓰기 도착 시각): 턴 1은 VAD가 늦고, 턴 2는 받아쓰기가 늦다
    turns = [("내일 오후 세 시요", 2.0, 2.35), ("네 맞아요", 9.0, 9.9)]
    for text, speech_end, stt_at in turns:
        await chain[0].push_frame(UserStoppedSpeakingFrame(speech_end + STOP_SECS))
        await chain[0].push_frame(TranscriptFrame(stt_at, text))
    lat = [round(s - e, 2) for s, (_, e, _) in zip(chain[-1].first_sound, turns)]
    print("대화 기록:", [m["role"] for m in ctx], "· 말 끝 → 첫 소리(초):", lat)
    check([m["role"] for m in ctx] == ["system", "user", "assistant", "user", "assistant"] and lat == [1.2, 1.5],
          "턴 1은 0.6+0.4+0.2=1.2초, 턴 2는 받아쓰기가 늦어 0.9+0.6=1.5초예요.")


asyncio.run(main())

assemble.typescript:
// D27 · Part 5 · 조립된 한 턴: VAD → STT → 사용자 턴 → LLM → TTS → 대화 기록 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d27_assemble.ts
//   턴 끝 판정 = '0.6초 조용함(VAD)'과 '받아쓰기 도착' 중 늦은 쪽, 그 뒤 LLM·TTS 첫 소리까지가 사용자가 느끼는 응답 시간
//   (대체: 실제 시간 대신 프레임에 적힌 가상 시각 t(초) · LLM·TTS는 고정 지연 0.4초·0.2초)
const STOP_SECS = 0.6;
const LLM_TTFB = 0.4;
const TTS_TTFB = 0.2;

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

interface Message {
  role: string;
  content: string;
}

interface Frame {
  kind: string;
  t: number; // 가상 시각(초)
  text?: string;
  messages?: Message[];
}

class FrameProcessor {
  nxt: FrameProcessor | null = null;
  async pushFrame(frame: Frame): Promise<void> {
    if (this.nxt) await this.nxt.processFrame(frame);
  }
  async processFrame(frame: Frame): Promise<void> {
    await this.pushFrame(frame);
  }
}

class UserAggregator extends FrameProcessor {
  context: Message[];
  stopped: number | null = null;
  arrived = 0;
  text: string | null = null;
  constructor(context: Message[]) {
    super();
    this.context = context;
  }
  async processFrame(frame: Frame): Promise<void> {
    if (frame.kind === "UserStoppedSpeakingFrame") this.stopped = frame.t;
    else if (frame.kind === "TranscriptFrame") {
      this.text = frame.text ?? "";
      this.arrived = frame.t;
    }
    if (this.stopped !== null && this.text !== null) {
      // 둘 다 모이면 턴 끝
      this.context.push({ role: "user", content: this.text });
      const end = Math.max(this.stopped, this.arrived);
      this.stopped = null;
      this.text = null;
      await this.pushFrame({ kind: "ContextFrame", t: end, messages: [...this.context] });
    }
  }
}

class LLM extends FrameProcessor {
  async processFrame(frame: Frame): Promise<void> {
    if (frame.kind === "ContextFrame") {
      const last = (frame.messages ?? [])[(frame.messages ?? []).length - 1];
      await this.pushFrame({ kind: "TextFrame", t: frame.t + LLM_TTFB, text: `${last.content}, 알겠습니다.` });
    }
  }
}

class TTS extends FrameProcessor {
  async processFrame(frame: Frame): Promise<void> {
    if (frame.kind === "TextFrame") {
      await this.pushFrame(frame); // 글자는 대화 기록용으로도 흘려보내고
      await this.pushFrame({ kind: "AudioFrame", t: frame.t + TTS_TTFB });
    }
  }
}

class AssistantAggregator extends FrameProcessor {
  context: Message[];
  firstSound: number[] = [];
  constructor(context: Message[]) {
    super();
    this.context = context;
  }
  async processFrame(frame: Frame): Promise<void> {
    if (frame.kind === "TextFrame") this.context.push({ role: "assistant", content: frame.text ?? "" });
    else if (frame.kind === "AudioFrame") this.firstSound.push(frame.t);
  }
}

const ctx: Message[] = [{ role: "system", content: "치과 예약 비서" }];
const tail = new AssistantAggregator(ctx);
const chain: FrameProcessor[] = [new FrameProcessor(), new UserAggregator(ctx), new LLM(), new TTS(), tail];
for (let i = 0; i + 1 < chain.length; i++) chain[i].nxt = chain[i + 1];
// [텍스트, 말 끝 시각, 받아쓰기 도착 시각]: 턴 1은 VAD가 늦고, 턴 2는 받아쓰기가 늦다
const turns: [string, number, number][] = [["내일 오후 세 시요", 2.0, 2.35], ["네 맞아요", 9.0, 9.9]];
for (const [text, speechEnd, sttAt] of turns) {
  await chain[0].pushFrame({ kind: "UserStoppedSpeakingFrame", t: speechEnd + STOP_SECS });
  await chain[0].pushFrame({ kind: "TranscriptFrame", t: sttAt, text });
}
const lat = tail.firstSound.map((s, i) => Math.round((s - turns[i][1]) * 100) / 100);
console.log("대화 기록:", ctx.map((m) => m.role).join(","), "· 말 끝 → 첫 소리(초):", lat.join(","));
check(ctx.map((m) => m.role).join() === "system,user,assistant,user,assistant" && lat.join() === "1.2,1.5", "턴 1은 0.6+0.4+0.2=1.2초, 턴 2는 받아쓰기가 늦어 0.9+0.6=1.5초예요.");

transport.typescript:
// D27 · Part 6 · Transport: 같은 비서를 WebSocket으로 — 메시지 ↔ Frame 번역기(Serializer) — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d27_transport.ts
//   파이프라인(STT → LLM → TTS)은 그대로 두고 입구·출구(Transport)만 바꿔 끼워도 같은 답이 나오는지 확인
//   (대체: 진짜 WebSocket 대신 같은 파일 안의 배열 큐)
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

interface Frame {
  kind: "audio" | "text";
  data?: Buffer;
  text?: string;
}

class Serializer {
  // 메시지(JSON 글자) ↔ Frame 번역기. 오디오 바이트는 base64로 감싼다
  serialize(f: Frame): string {
    return f.kind === "audio" ? JSON.stringify({ type: "audio", b64: (f.data ?? Buffer.alloc(0)).toString("base64") }) : JSON.stringify({ type: "text", text: f.text });
  }
  deserialize(msg: string): Frame {
    const d = JSON.parse(msg);
    return d.type === "audio" ? { kind: "audio", data: Buffer.from(d.b64, "base64") } : { kind: "text", text: d.text };
  }
}

function pipeline(frame: Frame): Frame[] {
  // STT → LLM → TTS를 한 함수로 압축한 '두뇌'. Transport가 무엇이든 이 함수는 그대로
  const heard = (frame.data ?? Buffer.alloc(0)).toString("utf-8"); // STT 흉내: 바이트가 곧 말
  const reply = `${heard}라고 하셨죠? 예약해 드릴게요.`; // LLM 흉내
  return [{ kind: "text", text: reply }, { kind: "audio", data: Buffer.from(reply, "utf-8") }]; // TTS 흉내
}

async function localTransport(frames: Frame[]): Promise<Frame[]> {
  // Transport A: 프레임을 그대로 주고받는 로컬
  return frames.flatMap(pipeline);
}

async function websocketTransport(frames: Frame[]): Promise<Frame[]> {
  // Transport B: 클라이언트가 JSON 메시지를 보내고, 서버가 풀어서 처리한 뒤 다시 JSON으로 돌려준다
  const ser = new Serializer();
  const up: string[] = frames.map((f) => ser.serialize(f)); // 클라이언트 → 서버
  const down: string[] = [];
  for (const msg of up) {
    await Promise.resolve(); // 메시지가 네트워크를 건너는 자리
    for (const out of pipeline(ser.deserialize(msg))) down.push(ser.serialize(out)); // 서버 → 클라이언트
  }
  return down.map((m) => ser.deserialize(m));
}

const frames: Frame[] = [{ kind: "audio", data: Buffer.from("내일 세 시", "utf-8") }];
const a = await localTransport(frames);
const b = await websocketTransport(frames);
console.log("로컬  :", a[0].text);
console.log("WS 경유:", b[0].text);
const same = JSON.stringify(a.map((f) => new Serializer().serialize(f))) === JSON.stringify(b.map((f) => new Serializer().serialize(f)));
const rt = new Serializer().deserialize(new Serializer().serialize(frames[0]));
check(same && rt.data?.equals(frames[0].data ?? Buffer.alloc(0)) === true, "Transport를 바꿔도 파이프라인 결과는 같아야 해요.");

recap.typescript:
// D27 · Part 7 · 오늘 정리: Pipecat 핵심 다섯 문장을 작은 실험으로 확인 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d27_recap.ts
//   ① Frame은 System·Data·Control ② 작업자는 모르는 Frame도 넘긴다 ③ upstream은 거꾸로 ④ 느린 일은 겹쳐 실행 ⑤ Transport는 갈아 끼운다
//   (대체: 개념 퀴즈 답을 코드로 계산해 표로 확인)
type Direction = "downstream" | "upstream";

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

class P {
  name: string;
  forward: boolean;
  nxt: P | null = null;
  prv: P | null = null;
  seen: string[] = [];
  constructor(name: string, forward: boolean = true) {
    this.name = name;
    this.forward = forward;
  }
  async process(frame: string, direction: Direction): Promise<void> {
    this.seen.push(`${frame}/${direction}`);
    const t = direction === "downstream" ? this.nxt : this.prv;
    if (this.forward && t) await t.process(frame, direction);
  }
}

const sleep = (ms: number): Promise<void> => new Promise((r) => setTimeout(r, ms));

const a = new P("A");
const b = new P("B", false);
const c = new P("C");
a.nxt = b;
b.prv = a;
b.nxt = c;
c.prv = b;
await a.process("EndFrame", "downstream"); // ② B가 넘기지 않으면 C는 영영 모른다
await c.process("Interrupt", "upstream"); // ③ C에서 위로 보내면 B가 받고(넘기지 않아) 멈춘다
const t0 = performance.now();
await Promise.all([sleep(100), sleep(100)]); // ④ 기다리는 일 둘을 겹쳐 실행
const overlap = performance.now() - t0 < 190;
const answers: Record<string, boolean | number> = {
  "System Frame은 큐를 새치기한다": true,
  "B가 EndFrame을 안 넘기면 C가 받은 Frame 수": c.seen.length - 1, // C의 기록 중 ③에서 직접 넣은 것 제외
  "upstream 신호를 B가 받았나": b.seen.includes("Interrupt/upstream"),
  "기다리는 일을 겹쳐 쓰면 합계보다 빨리 끝난다": overlap,
  "Transport만 바꾸면 파이프라인을 고쳐야 하나": false,
};
for (const [q, v] of Object.entries(answers)) console.log(`${q}: ${v}`);
check(answers["B가 EndFrame을 안 넘기면 C가 받은 Frame 수"] === 0 && answers["upstream 신호를 B가 받았나"] === true && overlap, "끊긴 Frame은 뒤에 닿지 않고, 기다리는 일은 겹쳐 실행돼야 해요.");
